preConditionHook:
// MultiWalk's WFSafe_AvgTrueRange is a ROLLING accumulator, not a fresh N-term
// sum: it is seeded once with a full sum on the study's first calculated bar and
// thereafter carries S += TrueRange - TrueRange[Length]. Its low bits therefore
// depend on every bar since the seed, and reproducing them means rolling the
// same way rather than recomputing more accurately.
//
// Measured on @OJ 240min (0.05 tick -- a 0.25-tick symbol cannot show this at
// all, because sums of dyadic values are exact): the rolling model reproduces
// TradeStation on 2,808 of 2,808 bars where a fresh sum manages 92, and it is
// what makes the 2015-02-20 profit target fire where a fresh sum leaves it a
// hair short. EL_WFSafeSeed_Probe.txt pins the seed: drift is 0 at each run's
// own first calculated bar and diverges with both MaxBarsBack and the chart
// start, so the seed is MaxBarsBack + 1 -- the first bar OnBarClose runs.
//
// atrLength != lookback also re-seeds, which is what the WFSafe_ wrappers do
// when a walkforward re-optimization changes the length.
if (atrLength != (int)lookback) {
    atrSum = 0.0;
    for (int i = 0; i < (int)lookback; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLength = (int)lookback;
} else {
    const int out = (int)lookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    // TWO statements, not one. EasyLanguage writes
    //     Summation = Summation[1] + Price - Price[Length]
    // which evaluates left to right as (S + in) - out. Folding it to
    // S + (in - out) is a different rounding and lands on the other side of the
    // threshold at @OJ 2015-02-20: (S+in)-out gives 1722.4999999999977 and
    // fires, S+(in-out) gives 1722.5000000000066 and does not.
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atr = atrSum / (int)lookback;
